import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.Crpw6aS5.js";const k=JSON.parse('{"title":"贡献指南与本地质量门禁","description":"","frontmatter":{},"headers":[],"relativePath":"guide/contributing.md","filePath":"guide/contributing.md","lastUpdated":1783686541000}'),t={name:"guide/contributing.md"};function l(p,s,h,r,o,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="贡献指南与本地质量门禁" tabindex="-1">贡献指南与本地质量门禁 <a class="header-anchor" href="#贡献指南与本地质量门禁" aria-label="Permalink to &quot;贡献指南与本地质量门禁&quot;">​</a></h1><p>这份文档说明贡献代码前应该如何在本地安装、开发、测试和运行质量门禁。目标是让维护者和贡献者都能在提交 PR 前回答一个问题：这次改动有没有破坏核心 Coding Agent 工作流。</p><h2 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h2><p>项目根目录使用 Bun：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>如果改动涉及 <code>desktop/</code>，也安装桌面端依赖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>如果改动涉及 <code>adapters/</code>，或者要运行 <code>check:adapters</code> / <code>check:native</code>，安装 adapter 依赖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adapters</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>不要提交本地运行产物，例如 <code>artifacts/quality-runs/</code>、<code>node_modules/</code>、<code>desktop/node_modules/</code>。</p><h2 id="普通-pr-的影响面检查" tabindex="-1">普通 PR 的影响面检查 <a class="header-anchor" href="#普通-pr-的影响面检查" aria-label="Permalink to &quot;普通 PR 的影响面检查&quot;">​</a></h2><p>先让仓库按变更路径列出需要运行的检查：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:impact</span></span></code></pre></div><p>开发时运行 impact report 选中的窄命令即可。准备声明 PR-ready、改动风险较高，或需要完整复现托管 CI 时，再运行统一入口：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p><code>bun run verify</code> 等价于 <code>bun run quality:pr</code>，会按改动范围执行被选中的 policy、desktop、server、adapter、native、provider contract、chat contract、persistence、docs 和 coverage lane。它不调用真实大模型。小范围外部贡献者不需要在本机运行无关模块；GitHub CI 会再次执行精确的 path-aware gate。</p><p>主质量报告会内嵌当前测试范围、结果矩阵、覆盖率摘要，并链接完整 coverage/JUnit/log artifact：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>artifacts/quality-runs/&lt;timestamp&gt;/report.md</span></span>
<span class="line"><span>artifacts/quality-runs/&lt;timestamp&gt;/report.json</span></span>
<span class="line"><span>artifacts/quality-runs/&lt;timestamp&gt;/junit.xml</span></span>
<span class="line"><span>artifacts/quality-runs/&lt;timestamp&gt;/logs/*.log</span></span>
<span class="line"><span>artifacts/coverage/&lt;timestamp&gt;/coverage-report.md</span></span>
<span class="line"><span>artifacts/coverage/&lt;timestamp&gt;/coverage-report.json</span></span></code></pre></div><p>PR 描述里请贴出你实际运行的命令和 summary。<code>quality:pr</code> / <code>quality:verify</code> 仍然保留给习惯显式质量命名的用户，但推荐文档和 AI prompt 都使用 <code>bun run verify</code>。</p><p>覆盖率门禁同时执行四件事：按源码口径统计覆盖率、执行 baseline ratchet、报告 75-80%+ 的目标差距，并对新增/变更的可执行生产代码行执行 changed-line coverage。当前 baseline 记录在 <code>scripts/quality-gate/coverage-baseline.json</code>，CI 会优先对比 base branch 的 baseline，新增 PR 不允许覆盖率下降超过允许窗口。<code>coverage-baseline.json</code> 或 <code>coverage-thresholds.json</code> 变更必须由维护者加 <code>allow-coverage-baseline-change</code> 后才能合并。Quarantine 只用于维护者的 baseline/release 追踪，不得隐藏确定性的 provider/chat 契约测试；当前普通 PR gate 不依赖 quarantine 才能通过。</p><h2 id="ai-coding-agent-修复循环" tabindex="-1">AI Coding Agent 修复循环 <a class="header-anchor" href="#ai-coding-agent-修复循环" aria-label="Permalink to &quot;AI Coding Agent 修复循环&quot;">​</a></h2><p>给 AI 写代码时，可以直接把这段作为验收指令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run \`bun run check:impact\`, then run the selected focused checks. If the task</span></span>
<span class="line"><span>requires PR-ready/full validation, run \`bun run verify\`. If it fails, read the latest</span></span>
<span class="line"><span>\`artifacts/quality-runs/&lt;timestamp&gt;/report.md\` and the relevant lane log,</span></span>
<span class="line"><span>fix the missing tests, coverage failures, type/lint/build errors, or docs/native</span></span>
<span class="line"><span>failures, then rerun \`bun run verify\` until it passes. Do not lower coverage</span></span>
<span class="line"><span>baselines or thresholds unless a maintainer explicitly requested it.</span></span></code></pre></div><p>Agent 应按这个顺序处理失败：</p><ol><li>先看 <code>artifacts/quality-runs/&lt;timestamp&gt;/report.md</code> 的 Summary 和 Result Matrix，定位失败 lane。</li><li>如果是 <code>Path-aware PR checks</code> 失败，优先看是否缺同区域测试、是否动了 CLI core、是否动了 coverage policy；不要用 override 绕过普通功能 PR。</li><li>如果是 <code>Coverage gate</code> 失败，打开 <code>artifacts/coverage/&lt;timestamp&gt;/coverage-report.md</code> 或 <code>coverage-report.json</code>，优先修 <code>changedLines.failures</code> 和 <code>failures</code>；<code>targetGaps</code> 是技术债提示，新改动应让触达区域变好。</li><li>如果是 desktop/server/adapters/native/docs 失败，读对应 <code>artifacts/quality-runs/&lt;timestamp&gt;/logs/&lt;lane&gt;.log</code>，补测试或修构建，再跑相关窄命令。</li><li>窄命令通过后，如果要声明 PR-ready/full validation，再跑一次 <code>bun run verify</code>。只有最终 Summary 是 <code>failed=0</code>，才可以这样声明。</li></ol><p>外部参考口径：</p><ul><li><a href="https://testing.googleblog.com/2020/08/code-coverage-best-practices.html" target="_blank" rel="noreferrer">Google Testing Blog</a>：60% acceptable、75% commendable、90% exemplary；changed/per-commit coverage 90% 是合理下限。</li><li><a href="https://learn.microsoft.com/en-us/visualstudio/test/using-code-coverage-to-determine-how-much-code-is-being-tested" target="_blank" rel="noreferrer">Microsoft Visual Studio / Azure DevOps 文档</a>：团队通常以约 80% 为目标，典型项目要求可为 75%，生成代码可以放宽。</li><li><a href="https://chromium.googlesource.com/chromiumos/platform/ec/+/main/docs/code_coverage.md" target="_blank" rel="noreferrer">ChromiumOS EC</a>：新增或变更行要求至少 80% 覆盖。</li></ul><h2 id="feature-quality-contract" tabindex="-1">Feature Quality Contract <a class="header-anchor" href="#feature-quality-contract" aria-label="Permalink to &quot;Feature Quality Contract&quot;">​</a></h2><p>所有新功能、bugfix 和行为变化都必须带着可验证证据交付。这条规则同时约束人和 AI Coding Agent：</p><ul><li>先声明变更面：<code>desktop</code>、<code>server</code>、<code>adapter</code>、<code>native</code>、<code>docs</code>、<code>provider/runtime</code>、<code>agent-loop</code> 或 <code>release</code>。</li><li><code>desktop/src</code>、<code>src/server</code>、<code>src/tools</code>、<code>src/utils</code>、<code>adapters</code> 下的生产代码变更必须同 PR 带同区域测试；除非维护者显式加 <code>allow-missing-tests</code>。</li><li>纯逻辑写单元测试；server/API/provider/runtime 写 API 或 request-shape 测试；桌面 UI/store/API 写 Vitest/Testing Library；跨 UI、WebSocket、provider proxy、native sidecar、发布打包的用户流程要补 E2E 或 agent-browser smoke。</li><li>agent loop、工具调用、provider 路由、模型选择、文件编辑、权限、会话恢复、桌面聊天改动，PR 内必须有 mock/fixture 测试；有 provider 条件时还要给 live smoke 或 baseline 证据。</li><li>覆盖率是功能的一部分。本项目按 Google/Microsoft 风格执行：生成物/构建产物不计入产品覆盖率，维护中的产品区域要逐步达到 75-80%+，新增或变更的可执行生产代码行必须满足 <code>coverage-thresholds.json</code> 里的 changed-line coverage 门槛。</li><li>不要为了过门禁随便降低 <code>coverage-baseline.json</code> 或 <code>coverage-thresholds.json</code>；确实要改时必须有 <code>allow-coverage-baseline-change</code> 和原因。历史低覆盖区域是技术债，新 PR 至少要让触达区域更好。</li><li>PR 描述必须写清楚：改了哪些文件、补了哪些测试、coverage 报告路径、E2E/live 报告路径或 blocker、剩余风险。</li></ul><h2 id="本机-push-前提醒" tabindex="-1">本机 Push 前提醒 <a class="header-anchor" href="#本机-push-前提醒" aria-label="Permalink to &quot;本机 Push 前提醒&quot;">​</a></h2><p>push 不再自动运行本地质量门禁。需要质量检查时，请手动运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:push</span></span></code></pre></div><p><code>bun run quality:push</code> 复用 PR gate 的 impact/policy/路径检查，但默认跳过耗时的 coverage lane；完整覆盖率仍保留在 <code>bun run verify</code>、<code>bun run quality:pr</code> 和 CI。</p><p>仍然可以安装本机 pre-push hook，但它只打印非阻塞提醒，不会卡住 <code>git push</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks:install</span></span></code></pre></div><p>拥有可信仓库环境和模型额度的维护者可以手动运行真实 provider smoke 和桌面 agent-browser smoke：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:providers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:smoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimax:main:minimax-main</span></span></code></pre></div><p>需要完整 live baseline 时使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-live</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimax:main:minimax-main</span></span></code></pre></div><h2 id="pr-ci-合并门禁" tabindex="-1">PR CI 合并门禁 <a class="header-anchor" href="#pr-ci-合并门禁" aria-label="Permalink to &quot;PR CI 合并门禁&quot;">​</a></h2><p><code>.github/workflows/pr-quality.yml</code> 会在 PR <code>opened</code>、<code>synchronize</code>、<code>reopened</code>、<code>ready_for_review</code>、<code>labeled</code>、<code>unlabeled</code> 时触发。<code>scope-plan</code> 不安装依赖，只负责稳定地产生影响面计划；<code>policy-enforcement</code> 独立安装锁定依赖并执行 policy，因此 policy 失败也不会吞掉产品测试结果。产品 job 只依赖 <code>scope-plan</code>，按路径选择 desktop、server、adapter、native、provider contract、chat contract、persistence、docs 和 coverage lane。最后的 <code>pr-quality-gate</code> 会严格核对每个 job：选中的必须 success，未选中的必须 skipped，cancelled 或缺失结果都不能误判为通过。</p><p>仓库侧应在 GitHub branch protection / ruleset 中保护 <code>main</code>，并把 <code>pr-quality-gate</code> 设为 required status check。CODEOWNERS 要求维护者审查 workflow、quality policy 以及 provider/WebSocket 等高风险边界；本机 hook 只做提醒，真正阻止低质量 merge 的是 PR gate。</p><h2 id="按改动范围补充测试" tabindex="-1">按改动范围补充测试 <a class="header-anchor" href="#按改动范围补充测试" aria-label="Permalink to &quot;按改动范围补充测试&quot;">​</a></h2><p>根据你改动的区域补充运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:server</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 服务端 API、WebSocket、provider、会话等测试</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:desktop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 桌面端 lint、Vitest、生产构建</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:adapters</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # IM adapter 测试</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:native</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 桌面 sidecar、Electron host 与 package-smoke 检查</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:provider-contract</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Provider/runtime/proxy 的离线契约测试</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:chat-contract</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # WebSocket、会话与桌面 chat store 契约测试</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:persistence-upgrade</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 持久化迁移和旧 fixture 兼容性</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:docs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 文档构建，使用 npm ci + docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:quarantine</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 维护者 baseline/release quarantine 审计</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:coverage</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # root、desktop、adapters 覆盖率报告和 ratchet 门禁</span></span></code></pre></div><p>如果只改了很窄的文件，先跑对应的定向测试即可；只有在声明 PR-ready/full validation 时才需要本地再跑 <code>bun run verify</code>，托管 CI 仍会执行所有被选中的必需 lane。</p><p>生产代码改动必须带对应测试文件：<code>desktop/src/**</code>、<code>src/server/**</code>、<code>src/tools/**</code>、<code>src/utils/**</code>、<code>adapters/**</code> 变更如果没有同区域测试，会触发阻断。只有维护者确认不适合自动化测试时，才能使用 <code>allow-missing-tests</code>。覆盖率 baseline/threshold 变更同样需要维护者确认并加 <code>allow-coverage-baseline-change</code>。</p><h2 id="真实模型-baseline" tabindex="-1">真实模型 Baseline <a class="header-anchor" href="#真实模型-baseline" aria-label="Permalink to &quot;真实模型 Baseline&quot;">​</a></h2><p><code>quality:baseline</code> 用来跑真实 Coding Agent 任务：启动本地服务端、创建隔离 fixture、让模型通过聊天修代码、跑测试，并保存 transcript、diff、verification log 和报告。它还会对 provider 进行 live smoke：已保存或当前激活的 OpenAI-compatible provider 会验证连通性、proxy 转换和流式 proxy 结果；env-only provider smoke 只验证上游连通性和转换管线。</p><p>默认命令不会调用真实模型：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:baseline</span></span></code></pre></div><p>要真正跑模型，必须显式加 <code>--allow-live</code> 并选择本机 provider。</p><p>先列出本机可用 provider 和可复制参数：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:providers</span></span></code></pre></div><p>输出示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Saved providers:</span></span>
<span class="line"><span>  MiniMax</span></span>
<span class="line"><span>    selector: minimax</span></span>
<span class="line"><span>    main: MiniMax-M2.7-highspeed</span></span>
<span class="line"><span>      --provider-model minimax:main:minimax-main</span></span></code></pre></div><p>复制输出里的参数运行 baseline：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-live</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimax:main:minimax-main</span></span></code></pre></div><p>如果只需要跑 provider smoke 和桌面 agent-browser smoke，而不跑全部 baseline case，可以使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:smoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimax:main:minimax-main</span></span></code></pre></div><p>可以一次跑多个模型：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-live</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --provider-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codingplan:main:codingplan-main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --provider-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimax:main:minimax-main</span></span></code></pre></div><p><code>provider</code> selector 来自桌面端「Settings &gt; Providers」里保存的本机配置。别人 clone 代码后不需要知道你的 provider UUID，也不需要使用你的供应商；他们可以在自己的桌面端添加 provider 后运行 <code>bun run quality:providers</code> 选择自己的模型。</p><p>如果没有保存 provider，也可以用环境变量跑一条 unsaved provider smoke：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QUALITY_GATE_PROVIDER_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://example.com</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QUALITY_GATE_PROVIDER_API_KEY=... </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QUALITY_GATE_PROVIDER_MODEL=model-id </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">QUALITY_GATE_PROVIDER_API_FORMAT=openai_chat </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bun </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-live</span></span></code></pre></div><h2 id="什么时候必须跑-baseline" tabindex="-1">什么时候必须跑 Baseline <a class="header-anchor" href="#什么时候必须跑-baseline" aria-label="Permalink to &quot;什么时候必须跑 Baseline&quot;">​</a></h2><p>以下改动在确定性 contract/E2E 通过后，建议由可信维护者补跑 live baseline：</p><ul><li>桌面聊天、会话恢复、WebSocket、CLI bridge</li><li>provider/model/runtime 选择</li><li>权限、工具调用、文件编辑、任务执行</li><li>agent-browser smoke、Computer Use、Skills、MCP</li><li>release 前或风险较大的跨模块重构</li></ul><p>来自 fork 的外部 PR 不会获得仓库 secrets，也不要求贡献者自费调用模型。请在 PR 里写明 <code>live model: not run (untrusted fork / no provider)</code>；高风险变更由维护者在合并或发版前补跑 live baseline。没有 live 证据不应让确定性 PR lane 产生随机失败。</p><h2 id="release-门禁" tabindex="-1">Release 门禁 <a class="header-anchor" href="#release-门禁" aria-label="Permalink to &quot;Release 门禁&quot;">​</a></h2><p>发版前使用 release 模式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-live</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --provider-model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">selecto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:main</span></span></code></pre></div><p>release 模式会组合 PR checks、baseline catalog、live baseline、native checks，并用当前平台 canonical release artifact 跑 <code>package-smoke --package-kind release</code>。发版报告同样写入 <code>artifacts/quality-runs/&lt;timestamp&gt;/</code>。线上 release workflow 在打包矩阵前会先跑 <code>bun run verify</code> 作为非 live 预检；真实 live release gate 仍需要维护者用可用 provider 显式运行。</p><p>release 模式下 live lane 不允许静默跳过。缺少 provider、真实模型额度或外部账号时，门禁会失败，并要求在发版记录里明确 blocker。</p><h2 id="pr-提交流程" tabindex="-1">PR 提交流程 <a class="header-anchor" href="#pr-提交流程" aria-label="Permalink to &quot;PR 提交流程&quot;">​</a></h2><ol><li>新建普通产品分支，例如 <code>fix/session-reconnect</code> 或 <code>feat/provider-quality-gate</code>。</li><li>安装依赖并完成改动。</li><li>为行为变化补测试。</li><li>运行相关定向测试。</li><li>可选：运行 <code>bun run hooks:install</code>，让后续 push 显示非阻塞提醒。</li><li>如果要声明 PR-ready/full validation，运行 <code>bun run verify</code>。</li><li>高风险改动由可信维护者运行 live baseline；外部贡献者记录未运行原因即可。</li><li>在 PR 描述里写清楚用户影响、测试命令、覆盖率/质量报告 summary、已知风险。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="没有-provider-可以跑吗" tabindex="-1">没有 provider 可以跑吗？ <a class="header-anchor" href="#没有-provider-可以跑吗" aria-label="Permalink to &quot;没有 provider 可以跑吗？&quot;">​</a></h3><p>可以。运行影响面检查和它选中的确定性命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:impact</span></span></code></pre></div><p><code>bun run verify</code> 也不需要真实模型；只有 live baseline 需要。维护者可以先在桌面端 Settings &gt; Providers 添加自己的 provider，再运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> quality:providers</span></span></code></pre></div><h3 id="provider-selector-冲突怎么办" tabindex="-1">provider selector 冲突怎么办？ <a class="header-anchor" href="#provider-selector-冲突怎么办" aria-label="Permalink to &quot;provider selector 冲突怎么办？&quot;">​</a></h3><p>如果两个 provider 名称生成了相同 selector，<code>quality:providers</code> 会退回输出 provider ID。直接复制它给出的 <code>--provider-model ...</code> 即可。</p><h3 id="模型-id-里带冒号怎么办" tabindex="-1">模型 ID 里带冒号怎么办？ <a class="header-anchor" href="#模型-id-里带冒号怎么办" aria-label="Permalink to &quot;模型 ID 里带冒号怎么办？&quot;">​</a></h3><p>优先使用角色选择，例如：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--provider-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> custom:haiku:custom-haiku</span></span></code></pre></div><p>脚本会把 <code>haiku</code> 解析成本机 provider 配置里的真实模型 ID。</p>`,89)])])}const g=i(t,[["render",l]]);export{k as __pageData,g as default};
